import{_ as o,o as t,c as r,a}from"./app.DLiRGumz.js";const h=JSON.parse('{"title":"MCP Server Tool Extraction — Proposal","description":"","frontmatter":{"title":"MCP Server Tool Extraction — Proposal","date":"2026-02-21T00:00:00.000Z","status":"implemented","owner":"agent-f (B90-W2-F1)","tags":["wl-126","b90","monolith-split","mcp"]},"headers":[],"relativePath":"changes/mcp-server-extraction/proposal.md","filePath":"changes/mcp-server-extraction/proposal.md","lastUpdated":1771678191000}'),i={name:"changes/mcp-server-extraction/proposal.md"};function s(n,e,l,c,p,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="proposal-extract-tool-groups-from-mcp-server-py" tabindex="-1">Proposal: Extract Tool Groups from mcp/server.py <a class="header-anchor" href="#proposal-extract-tool-groups-from-mcp-server-py" aria-label="Permalink to &quot;Proposal: Extract Tool Groups from mcp/server.py&quot;">​</a></h1><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p><code>src/thegent/mcp/server.py</code> grew to 3,944 lines pre-wave-2 (3,939 post-wave-2), well above the 500-line module ceiling. The file contained registration logic for 13+ independent tool groups (sessions, queue, terminal, escalation, governance, research, planning, contract_observe, locking_planning, skills, coordination, runtime, batch4) each with its own <code>_load_server_tools_&lt;group&gt;_module()</code> factory and registration handler.</p><p>These tool groups are independent domains — sessions tooling has no logical dependency on escalation tooling, for example. Keeping them in a single file causes:</p><ol><li><strong>Review friction</strong>: Any change to one tool group requires parsing 3.9k lines.</li><li><strong>Merge conflicts</strong>: Parallel agents modifying different tool groups always conflict.</li><li><strong>Test isolation impossible</strong>: Cannot import and test a single tool group without loading the entire server module.</li></ol><h2 id="why-this-extraction" tabindex="-1">Why This Extraction <a class="header-anchor" href="#why-this-extraction" aria-label="Permalink to &quot;Why This Extraction&quot;">​</a></h2><ol><li><p><strong>Tool group isolation</strong>: Each tool group is a coherent domain (sessions, queue, governance, research, planning, etc.). Extracting them to <code>mcp/server/&lt;group&gt;.py</code> enables independent development and testing.</p></li><li><p><strong>LOC reduction</strong>: The <code>server/</code> subdirectory pattern already exists — 24 tool group modules live there (<code>tools_sessions.py</code>, <code>tools_governance.py</code>, etc.). The <code>server.py</code> monolith only needed to be updated to delegate to these existing modules via its <code>_load_server_tools_&lt;group&gt;_module()</code> pattern.</p></li><li><p><strong>Zero business logic duplication</strong>: The extracted modules own the tool definitions; <code>server.py</code> acts as the router/registrar only.</p></li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Keep <code>server.py</code> as the registrar/lifespan/middleware entry point. All tool group implementations live in <code>src/thegent/mcp/server/&lt;group&gt;.py</code>. The <code>server.py</code> module loads each group at startup via the <code>_load_server_tools_&lt;group&gt;_module()</code> pattern (already in place post-extraction).</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li><code>server.py</code> &lt; 4,000 lines (ceiling; target &lt; 2,000 in wave-5).</li><li>All 13+ tool group modules exist under <code>src/thegent/mcp/server/</code>.</li><li><code>python -c &quot;from thegent.mcp.server import app&quot;</code> exits 0 in &lt; 2s.</li><li>MCP test suite passes without modification.</li></ul>',11)])])}const m=o(i,[["render",s]]);export{h as __pageData,m as default};
